"use client";

import { useState, useRef } from "react";
import { motion, AnimatePresence } from "framer-motion";
import Hero from "@/components/Hero";
import Timeline from "@/components/Timeline";
import Venue from "@/components/Venue";
import Gallery from "@/components/Gallery";
import RSVP from "@/components/RSVP";
import MusicPlayer from "@/components/MusicPlayer";

export default function WeddingPage() {
  const [isOpen, setIsOpen] = useState(false);
  const audioRef = useRef<HTMLAudioElement | null>(null);

  // Open Invitation ခလုတ် နှိပ်လိုက်ချိန် လုပ်ဆောင်မည့် function
  const handleOpenInvitation = () => {
    setIsOpen(true);

    // နောက်ခံသီချင်း စတင်ဖွင့်ခြင်း
    if (audioRef.current) {
      audioRef.current.play().catch(() => {
        console.log("Audio autoplay was prevented");
      });
    }

    // အောက်ဘက်သို့ ချောမွေ့စွာ scroll ဆင်းပေးခြင်း
    setTimeout(() => {
      document.getElementById("main-content")?.scrollIntoView({ behavior: "smooth" });
    }, 100);
  };

  return (
    <main className="min-h-screen bg-[#FAF7F2] text-stone-800 selection:bg-amber-100">
      {/* နောက်ခံ အသံဖိုင် (public/music.mp3 ဟု ထားပေးပါ) */}
      <audio ref={audioRef} src="/music.mp3" loop preload="auto" />

      {/* အပေါ်ဆုံး မျက်နှာဖုံး / Hero Cover အပိုင်း */}
      <Hero onOpenInvitation={handleOpenInvitation} isOpen={isOpen} />

      {/* OPEN INVITATION နှိပ်ပြီးမှ ပေါ်လာမည့် ကျန်အပိုင်းများ */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            id="main-content"
            initial={{ opacity: 0, y: 30 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8, ease: "easeOut" }}
          >
            {/* အစီအစဉ်များ၊ နေရာနှင့် RSVP အပိုင်းများ */}
            <Timeline />
            <Venue />
            <Gallery />
            <RSVP />

            {/* သီချင်း ဖွင့်/ပိတ် ထိန်းချုပ်ခလုတ် */}
           <MusicPlayer/>
          </motion.div>
        )}
      </AnimatePresence>
    </main>
  );
}